package com.kjalumni.announcement.repository;
import com.kjalumni.announcement.entity.Announcement; import com.kjalumni.auth.entity.User; import com.kjalumni.common.enums.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import java.util.UUID;
public interface AnnouncementRepository extends JpaRepository<Announcement,UUID> { Page<Announcement> findByCreatedByOrderByCreatedAtDesc(User user, Pageable pageable); @Query("select a from Announcement a where a.createdBy = :user or a.createdBy.branch is null order by a.createdAt desc") Page<Announcement> findCreatedByUserOrSuperAdmin(User user, Pageable pageable); @Query("select a from Announcement a where a.status=:status and (a.visibility=com.kjalumni.common.enums.EventVisibility.ALL or a.branch=:branch) order by a.createdAt desc") Page<Announcement> findVisibleToBranch(Branch branch, AnnouncementStatus status, Pageable pageable); }
